{
  "name": "XIA xMAP多通道数字脉冲处理器",
  "name_en": "XIA xMAP Multi-Channel Digital Pulse Processor",
  "manufacturer": "XIA LLC",
  "description": "这是一种用于辐射探测器读出的多通道数字脉冲处理与多道分析电子学设备，可采集能谱、进行ROI区域统计、执行逐像素mapping，并将测量数据保存为文件。常用于X射线荧光、能谱分析及同步扫描实验。",
  "description_en": "This is a multi-channel digital pulse processing and multichannel analysis instrument for radiation detector readout. It acquires spectra, performs ROI-based counting, supports pixel-by-pixel mapping, and saves measurement data to files. It is commonly used for X-ray fluorescence, spectral analysis, and scanning experiments.",
  "tag_hints": [
    "X-ray fluorescence spectroscopy",
    "digital pulse processing",
    "multi-channel analyzer",
    "ROI analysis",
    "spectral mapping",
    "MCA acquisition",
    "detector readout"
  ],
  "actions": [
    {
      "action_name": "auto-FileCaptureOff",
      "description": "关闭数据文件捕获",
      "description_en": "disable data file capture"
    },
    {
      "action_name": "auto-FileCaptureOn",
      "description": "开启数据文件捕获",
      "description_en": "enable data file capture"
    },
    {
      "action_name": "auto-FileWriteComplete",
      "description": "检查数据文件写入是否完成",
      "description_en": "check whether data file writing is complete"
    },
    {
      "action_name": "auto-MCAMode",
      "description": "切换到MCA映射采集模式",
      "description_en": "switch to MCA mapping acquisition mode"
    },
    {
      "action_name": "auto-SCAMode",
      "description": "切换到SCA映射模式",
      "description_en": "switch to SCA mapping mode"
    },
    {
      "action_name": "auto-SpectraMode",
      "description": "切换到MCA能谱模式",
      "description_en": "switch to MCA spectra mode"
    },
    {
      "action_name": "auto-Write_CurrentConfig",
      "description": "保存当前配置",
      "description_en": "save the current configuration"
    },
    {
      "action_name": "auto-fileGet",
      "description": "读取文件输出参数",
      "description_en": "get a file output parameter"
    },
    {
      "action_name": "auto-filePut",
      "description": "设置文件输出参数",
      "description_en": "set a file output parameter"
    },
    {
      "action_name": "auto-finish_pixels",
      "description": "完成当前扫描的剩余像素",
      "description_en": "advance through the remaining pixels of the current scan"
    },
    {
      "action_name": "auto-getFileName",
      "description": "获取文件名",
      "description_en": "get the file name"
    },
    {
      "action_name": "auto-getFileNameByIndex",
      "description": "按序号获取文件名",
      "description_en": "get the file name by index"
    },
    {
      "action_name": "auto-getFileNumber",
      "description": "获取文件编号",
      "description_en": "get the file number"
    },
    {
      "action_name": "auto-getFilePath",
      "description": "获取文件路径",
      "description_en": "get the file path"
    },
    {
      "action_name": "auto-getFileTemplate",
      "description": "获取文件名模板",
      "description_en": "get the file name template"
    },
    {
      "action_name": "auto-getLastFileName",
      "description": "获取最近写入的文件名",
      "description_en": "get the most recently written file name"
    },
    {
      "action_name": "auto-nextFileNumber",
      "description": "递增到下一个文件编号",
      "description_en": "advance to the next file number"
    },
    {
      "action_name": "auto-next_pixel",
      "description": "推进到下一个像素",
      "description_en": "advance to the next pixel"
    },
    {
      "action_name": "auto-readmca",
      "description": "读取MCA能谱数据",
      "description_en": "read MCA spectrum data"
    },
    {
      "action_name": "auto-restore_rois",
      "description": "从文件恢复ROI设置",
      "description_en": "restore ROI settings from a file"
    },
    {
      "action_name": "auto-roi_calib_info",
      "description": "读取ROI与能量校准信息",
      "description_en": "retrieve ROI and energy calibration information"
    },
    {
      "action_name": "auto-setFileName",
      "description": "设置文件名",
      "description_en": "set the file name"
    },
    {
      "action_name": "auto-setFileNumCapture",
      "description": "设置写入文件的捕获数量",
      "description_en": "set the number of frames or buffers to capture to file"
    },
    {
      "action_name": "auto-setFileNumber",
      "description": "设置文件编号",
      "description_en": "set the file number"
    },
    {
      "action_name": "auto-setFilePath",
      "description": "设置文件路径",
      "description_en": "set the file path"
    },
    {
      "action_name": "auto-setFileTemplate",
      "description": "设置文件名模板",
      "description_en": "set the file name template"
    },
    {
      "action_name": "auto-setFileWriteMode",
      "description": "设置文件写入模式",
      "description_en": "set the file write mode"
    },
    {
      "action_name": "auto-start",
      "description": "开始采集",
      "description_en": "start acquisition"
    },
    {
      "action_name": "auto-stop",
      "description": "停止采集",
      "description_en": "stop acquisition"
    },
    {
      "action_name": "auto-total",
      "description": "获取ROI内总计数",
      "description_en": "get total counts in the ROI"
    },
    {
      "action_name": "auto-sum",
      "description": "获取求和计数",
      "description_en": "get summed counts"
    },
    {
      "action_name": "auto-net",
      "description": "获取ROI内净计数",
      "description_en": "get net counts in the ROI"
    },
    {
      "action_name": "auto-center",
      "description": "获取ROI中心道址",
      "description_en": "get the ROI center channel"
    },
    {
      "action_name": "auto-width",
      "description": "获取ROI宽度",
      "description_en": "get the ROI width"
    },
    {
      "action_name": "auto-clear",
      "description": "清除ROI设置",
      "description_en": "clear the ROI setting"
    },
    {
      "action_name": "auto-get_counts",
      "description": "获取通道计数谱",
      "description_en": "get channel count spectrum"
    },
    {
      "action_name": "auto-get_rois",
      "description": "获取ROI设置",
      "description_en": "get ROI settings"
    },
    {
      "action_name": "auto-del_roi",
      "description": "删除ROI",
      "description_en": "delete an ROI"
    },
    {
      "action_name": "auto-add_roi",
      "description": "添加ROI",
      "description_en": "add an ROI"
    },
    {
      "action_name": "auto-set_rois",
      "description": "定义ROI设置",
      "description_en": "define ROI settings"
    },
    {
      "action_name": "auto-clear_rois",
      "description": "清除全部ROI设置",
      "description_en": "clear all ROI settings"
    },
    {
      "action_name": "auto-get_calib",
      "description": "获取能量校准参数",
      "description_en": "get energy calibration parameters"
    },
    {
      "action_name": "auto-get_energy",
      "description": "获取能量刻度",
      "description_en": "get the energy scale"
    }
  ]
}

